3	import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from "react";
4	import { createAudioDirector, DEFAULT_AUDIO_SETTINGS, type AudioDirector, type AudioSettings } from "@/lib/game/audio/audioDirector";
5	import { readAudioSettings, writeAudioSettings } from "@/lib/game/audio/settings";
6	import { AUTOSAVE_INTERVAL_MS, HOTBAR_SLOTS, MAX_HUNGER, MAX_HEARTS, MAX_OXYGEN } from "@/lib/game/config";
7	import { GameEngine } from "@/lib/game/engine/GameEngine";
8	import type { GameApi, GameSnapshot } from "@/lib/game/engine/state";
9	import { createInputController, type InputController } from "@/lib/game/input/inputController";
10	import * as inv from "@/lib/game/inventory";
11	import { getSkinPreset, type SkinId } from "@/lib/game/playerSkins";
12	import { type Profile, setProfileSkin } from "@/lib/game/profiles";
13	import { createEmptyArmorEquipment, createInitialInventory, ITEM_DEF_BY_ID } from "@/lib/game/items";
14	import { RECIPES } from "@/lib/game/recipes";
15	import { GameRenderer } from "@/lib/game/render/GameRenderer";
16	import { createMinimapRenderer, type MinimapRenderer } from "@/lib/game/render/minimap";
17	import { readSave, writeSave } from "@/lib/game/save";
18	import type { EnchantmentId, Recipe } from "@/lib/game/types";
19	import { type WorldMeta, worldSaveKey } from "@/lib/game/worlds";
20	
21	/**
22	 * Thin React shell around the headless GameEngine and the GameRenderer.
23	 *
24	 * The engine is created in the canvas mount's callback ref (commit phase) and
25	 * held in React state; the UI reads it through useSyncExternalStore snapshots
26	 * and sends intents back as engine commands. The effect below owns everything
27	 * with a lifecycle: renderer, input listeners, the rAF loop, and autosave.
28	 */
29	
30	// Pre-mount snapshot (also the SSR snapshot): the starter loadout at full stats.
31	const PRE_MOUNT_SNAPSHOT: GameSnapshot = {
32	  api: null,
33	  inventory: createInitialInventory(),
34	  equippedArmor: createEmptyArmorEquipment(),
35	  selectedSlot: 0,
36	  hearts: MAX_HEARTS,
37	  hunger: MAX_HUNGER,
38	  oxygen: MAX_OXYGEN,
39	  daylightPercent: 100,
40	  passiveCount: 0,
41	  hostileCount: 0,
42	  respawnSeconds: 0,
43	  inventoryOpen: false,
44	  paused: false,
45	  debugOpen: false,
46	  debug: null,
47	  cameraMode: "first",
48	  armorPoints: 0,
49	  capsActive: false,
50	  sleeping: false,
51	  craftingStation: null,
52	  container: null,
53	  boss: null,
54	  victory: false,
55	  activeEffects: [],
56	  xpLevel: 0,
57	  xpProgress: 0
58	};
59	
60	const noopSubscribe = () => () => {};
61	
62	type GameContext = { engine: GameEngine; node: HTMLDivElement };
63	
64	// Debug/test handle: lets the browser console and the Playwright E2E suite
65	// inspect the live simulation (single-player client game — nothing to protect).
66	declare global {
67	  interface Window {
68	    __monecraft?: { engine: GameEngine; renderer: GameRenderer; input: InputController; audio: AudioDirector };
69	  }
70	}
71	
72	function persistGame(api: GameApi, saveKey: string, onMessage: (text: string) => void): void {
73	  try {
74	    writeSave(saveKey, api.serialize());
75	    onMessage("Saved");
76	  } catch {
77	    onMessage("Save failed");
78	  }
79	}
80	
81	/**
82	 * One mounted game = one world played by one profile. The owning shell remounts
83	 * this hook (via a React `key` on the world id) to switch worlds, so the
84	 * per-world save key and the profile are fixed for the hook's lifetime.
85	 */
86	export type UseMinecraftGameOptions = {
87	  world: WorldMeta;
88	  profile: Profile;
89	  /** Leave this world and return to the world list (the shell unmounts us). */
90	  onQuitToWorlds: () => void;
91	  /** Re-read this world from disk by forcing a fresh mount (used by Load/Reset). */
92	  onReloadWorld: () => void;
93	};
94	
95	export function useMinecraftGame(opts: UseMinecraftGameOptions) {
96	  // The owning shell keys this hook by world id, so the world is fixed for the
97	  // mount's life; capturing it once in refs lets the long-lived rAF/autosave
98	  // effect read the save key and seed without re-subscribing.
99	  const saveKeyRef = useRef(worldSaveKey(opts.world.id));
100	  const worldSeedRef = useRef(opts.world.seed);
101	  const worldTypeRef = useRef(opts.world.worldType);
102	  const [ctx, setCtx] = useState<GameContext | null>(null);
103	  const [locked, setLocked] = useState(false);
104	  const [saveMessage, setSaveMessage] = useState("");
105	  const [rendererError, setRendererError] = useState<string | null>(null);
106	  const [audioSettings, setAudioSettings] = useState<AudioSettings>(DEFAULT_AUDIO_SETTINGS);
107	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
108	  const minimapNodeRef = useRef<HTMLDivElement | null>(null);
109	  const audioRef = useRef<AudioDirector | null>(null);
110	  // The rAF effect must not re-run on volume tweaks — it reads through a ref.
111	  const audioSettingsRef = useRef(audioSettings);
112	  const [skinId, setSkinId] = useState<SkinId>(opts.profile.skinId);
113	  const skinIdRef = useRef(skinId);
114	  const rendererRef = useRef<GameRenderer | null>(null);
115	  // Pending UI timers (flash messages, world-reload defers) so they can be
116	  // cancelled on unmount instead of firing setState/onReloadWorld after teardown.
117	  const pendingTimeoutsRef = useRef<Set<number>>(new Set());
118	  // Set by Load/Reset before they force a remount: those want to re-read (or
119	  // discard) the on-disk save, so the unmount must NOT persist the live state
120	  // over it. Consumed once by the cleanup; every other unmount saves.
121	  const skipUnmountSaveRef = useRef(false);
122	
123	  // Audio is a global preference loaded after mount: render never touches
124	  // localStorage (SSR), and the setState hops a microtask like the
125	  // renderer-error report. This effect runs before the renderer effect (ctx is
126	  // set by a callback ref in a later commit), so the ref is populated by the
127	  // time either exists. The skin is per-profile and comes in via opts, not here.
128	  useEffect(() => {
129	    const stored = readAudioSettings();
130	    audioSettingsRef.current = stored;
131	    audioRef.current?.setSettings(stored);
132	    queueMicrotask(() => setAudioSettings(stored));
133	  }, []);
134	
135	  const updateAudioSettings = useCallback((partial: Partial<AudioSettings>) => {
136	    const next = { ...audioSettingsRef.current, ...partial };
137	    audioSettingsRef.current = next;
138	    setAudioSettings(next);
139	    writeAudioSettings(next);
140	    audioRef.current?.setSettings(next);
141	  }, []);
142	
143	  const updateSkin = useCallback(
144	    (id: SkinId) => {
145	      skinIdRef.current = id;
146	      setSkinId(id);
147	      setProfileSkin(opts.profile.id, id);
148	      rendererRef.current?.setPlayerSkin(getSkinPreset(id).palette);
149	    },
150	    [opts.profile.id]
151	  );
152	
153	  // Callback ref: the engine boots as soon as the canvas mount exists. A ref
154	  // callback runs during commit, where side effects and setState are legal.
155	  const attachMount = useCallback((node: HTMLDivElement | null) => {
156	    if (!node) {
157	      setCtx(null);
158	      return;
159	    }
160	    // A saved blob carries its own seed + type (engine prefers them); a fresh
161	    // world (no blob yet) boots from the world's stored seed and type.
162	    setCtx({
163	      engine: new GameEngine({ save: readSave(saveKeyRef.current), seed: worldSeedRef.current, worldType: worldTypeRef.current }),
164	      node
165	    });
166	  }, []);
167	
168	  // The minimap container mounts independently of the canvas; the rAF loop
169	  // below picks it up lazily once both exist.
170	  const attachMinimap = useCallback((node: HTMLDivElement | null) => {
171	    minimapNodeRef.current = node;
172	  }, []);
173	
174	  const engine = ctx?.engine ?? null;
175	  const subscribe = useMemo(() => engine?.subscribe ?? noopSubscribe, [engine]);
176	  const getSnapshot = useMemo(() => engine?.getSnapshot ?? (() => PRE_MOUNT_SNAPSHOT), [engine]);
177	  const getServerSnapshot = useCallback(() => PRE_MOUNT_SNAPSHOT, []);
178	  const snapshot = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
179	
180	  // Tracks each timer so unmount can cancel it; the timer also self-removes when
181	  // it fires so the set never grows unbounded.
182	  const scheduleTimeout = useCallback((fn: () => void, ms: number) => {
183	    const id = window.setTimeout(() => {
184	      pendingTimeoutsRef.current.delete(id);
185	      fn();
186	    }, ms);
187	    pendingTimeoutsRef.current.add(id);
188	  }, []);
189	
190	  useEffect(
191	    () => () => {
192	      for (const id of pendingTimeoutsRef.current) window.clearTimeout(id);
193	      pendingTimeoutsRef.current.clear();
194	    },
195	    []
196	  );
197	
198	  const flashMessage = useCallback(
199	    (text: string, durationMs = 1200) => {
200	      setSaveMessage(text);
201	      scheduleTimeout(() => setSaveMessage(""), durationMs);
202	    },
203	    [scheduleTimeout]
204	  );
205	
206	  useEffect(() => {
207	    if (!ctx) return;
208	    const { engine: gameEngine, node } = ctx;
209	
210	    const created = GameRenderer.create(node);
211	    if (!created.ok) {
212	      // Microtask: reporting an init failure from inside the effect body
213	      // would count as a cascading synchronous setState.
214	      queueMicrotask(() => setRendererError(created.error));
215	      return;
216	    }
217	    const renderer = created.renderer;
218	    canvasRef.current = renderer.domElement;
219	    rendererRef.current = renderer;
220	    // Before the first rAF, so no frame can ever show the default palette.
221	    renderer.setPlayerSkin(getSkinPreset(skinIdRef.current).palette);
222	
223	    const audio = createAudioDirector();
224	    audio.setSettings(audioSettingsRef.current);
225	    audioRef.current = audio;
226	    const input = createInputController({
227	      canvas: renderer.domElement,
228	      engine: gameEngine,
229	      onResize: () => renderer.handleResize(),
230	      onLockChange: (isLocked) => {
231	        // Pointer-lock acquisition is itself a user gesture — a safe unlock
232	        // point, and it re-resumes a context suspended by the browser.
233	        if (isLocked) audio.unlock();
234	        setLocked(isLocked);
235	      }
236	    });
237	
238	    // Autoplay policy: the AudioContext may only start inside a user gesture.
239	    const unlockAudio = () => audio.unlock();
240	    document.addEventListener("mousedown", unlockAudio);
241	    document.addEventListener("keydown", unlockAudio);
242	
243	    // The save key is fixed for the mount's life (the shell keys this hook by
244	    // world id), so capture it once — also keeps it out of the cleanup's ref read.
245	    const saveKey = saveKeyRef.current;
246	    const autoSave = () => persistGame(gameEngine, saveKey, flashMessage);
247	    const autoSaveId = window.setInterval(autoSave, AUTOSAVE_INTERVAL_MS);
248	    window.addEventListener("beforeunload", autoSave);
249	
250	    window.__monecraft = { engine: gameEngine, renderer, input, audio };
251	
252	    let minimap: MinimapRenderer | null = null;
253	    let last = performance.now();
254	    let animationFrame = 0;
255	    // Catch-up stepping: a slow frame (software GL, busy machine) can take far
256	    // longer than one 50ms step, and a single clamped step would run the
257	    // simulation in slow motion. Bounded substeps keep sim time tracking wall
258	    // time; the cap bounds work per frame and quietly drops time beyond it
259	    // (e.g. after a background-tab stall).
260	    const MAX_STEP_SECONDS = 0.05;
261	    const MAX_SUBSTEPS = 5;
262	    let pendingSeconds = 0;
263	    const clock = () => {
264	      const now = performance.now();
265	      pendingSeconds = Math.min(pendingSeconds + (now - last) / 1000, MAX_STEP_SECONDS * MAX_SUBSTEPS);
266	      last = now;
267	
268	      let frameSeconds = 0;
269	      while (pendingSeconds > 0) {
270	        const dt = Math.min(pendingSeconds, MAX_STEP_SECONDS);
271	        gameEngine.step(dt, input.input);
272	        pendingSeconds -= dt;
273	        frameSeconds += dt;
274	      }
275	
276	      for (const event of gameEngine.consumeEvents()) {
277	        if (event.type === "died" || event.type === "bossDefeated") {
278	          // Free the cursor so the death/victory button is clickable; the pause
279	          // command ignores both states, so the lock-loss won't open the menu too.
280	          input.clearKeys();
281	          if (document.pointerLockElement === renderer.domElement) document.exitPointerLock();
282	        }
283	        if (event.type === "respawned") input.clearKeys();
284	        if (event.type === "attackSwung") renderer.triggerSwing();
